void dei_led_execute( void )
{
	static Boolean do_once = FALSE ; 

    out_fifo_exec( NULL , dei_led_fifo ) ; 

	if( dei_led_sleep_tmr == DEI_LED_TIMEOUT_SLEEP )
	{		
		if( !do_once )
		{
			dei_led_flash_sleep();

			do_once = TRUE ; 
		}
	}
	else
	{
		dei_led_sleep_tmr ++ ; 

		do_once = FALSE ;
	}
	
	vrtc_update( dei_led_vrtc , 1 ) ; 

	vrtc_start( dei_led_vrtc ) ;
}


